// AfKing boxes are bought at the daily stamp (AfkingDelivered, no LootBoxBuy) and opened later
// inside whoever's mineFlip runs the work, under index 0 (LootboxModule.resolveAfkingBox). A box
// that rolls a spin emits only BoxSpin, whose betId carries no index, so nothing in its receipt
// ties it to the subscriber's box: ~40% of afKing boxes were invisible on run 75.
//
// The betId does carry the low 60 bits of the spin's seed, and the afKing seed is public once the
// word lands: hash2(hash4(word, playerId, AFKING_BOX_TAG, stampDay), spinTag). The word is the
// session word published by the latest LootboxRngApplied before the open; the stamp day is the
// delivered day in the player's latest AfkingDelivered (bits 128-151). Matching it is exact.
import { AbiCoder, keccak256 } from '../vendor/ethers-app.mjs';
import { eventFacts } from './facts.js';
import { compareLogs } from './client.js';

const coder = AbiCoder.defaultAbiCoder();
const AFKING_BOX_TAG = 0x41666b696e67426f78n; // "AfkingBox"
// "WwxrpSpin", "BurnieSpin", "EthSpin" (LootboxModule BOX_*_SPIN_TAG).
const SPIN_TAGS = [24n, 18n, 17n, 22n];
const LOW60 = (1n << 60n) - 1n;
const DAY_SHIFT = 128n;
const DAY_MASK = 0xffffffn;
const SPEND_MASK = (1n << 128n) - 1n;
// Several session words and more than one game day of deliveries on Sepolia timing.
const LOOKBACK_BLOCKS = 1200;

const hash = (types, values) => BigInt(keccak256(coder.encode(types, values)));

/** True when `betId` is the spin of this player's afKing box for (word, day). */
export function afkingSpinMatches({ betId, playerId, word, day }) {
  let id;
  try { id = BigInt(betId); } catch { return false; }
  const seed = hash(['uint256', 'uint256', 'uint256'], [13n, BigInt(word), BigInt(playerId)]);
  return SPIN_TAGS.some(tag => (hash(['uint256', 'uint256'], [tag, seed]) & LOW60) === (id & LOW60));
}

/** Decode AfkingDelivered.packed: [0..127] ETH in, [128..151] delivered day. */
export function afkingDelivery(packed) {
  const value = BigInt(packed ?? 0);
  return { day: Number((value >> DAY_SHIFT) & DAY_MASK), spendRawWei: value & SPEND_MASK };
}

// One fetch per (session, key) covering [row - LOOKBACK, head]; an older row fetches only the
// missing older slice, so a newest-first feed page costs one read per key, not one per row.
async function cachedRows(s, key, names, options, row, signal) {
  if (!s.afkingBoxRows) s.afkingBoxRows = new Map();
  const from = Math.max(0, Number(row.blockNumber) - LOOKBACK_BLOCKS);
  const read = (fromBlock, toBlock) => eventFacts(s, names, {
    contract: 'GAME', ...options, fromBlock, ...(toBlock == null ? {} : { toBlock }), signal,
  });
  const cached = s.afkingBoxRows.get(key);
  if (cached && cached.from <= from) return cached.rows;
  const rows = cached
    ? Promise.all([read(from, cached.from - 1), cached.rows]).then(([older, newer]) => [...older, ...newer].sort(compareLogs))
    : read(from).then(list => list.slice().sort(compareLogs));
  s.afkingBoxRows.set(key, { from, rows });
  try { return await rows; } catch (error) {
    if (cached) s.afkingBoxRows.set(key, cached); else s.afkingBoxRows.delete(key);
    throw error;
  }
}

const latestBefore = (rows, row) => {
  let found = null;
  for (const candidate of rows) {
    if (compareLogs(candidate, row) >= 0) break;
    found = candidate;
  }
  return found;
};

/**
 * The wallet's latest AfkingDelivered before `row`, decoded, or null. Rows come back decorated
 * (wallet-events.js), so the filter takes the address and is translated to the ID topic.
 */
export async function afkingDeliveryBefore(s, player, row, signal) {
  if (!player) return null;
  const address = String(player).toLowerCase();
  const rows = await cachedRows(s, `delivered:${address}`, ['AfkingDelivered'], { filters: { player: address } }, row, signal);
  const delivery = latestBefore(rows, row);
  return delivery ? { ...afkingDelivery(delivery.args.packed), row: delivery } : null;
}

/** For an anchorless BoxSpin: the afKing delivery it settles, or null when it is not one. */
export async function afkingSpinBox(s, row, signal) {
  const a = row.args;
  const playerId = a.playerId ?? a.id;
  if (playerId == null || a.betId == null) return null;
  const delivery = await afkingDeliveryBefore(s, a.player, row, signal);
  if (!delivery || !delivery.day) return null;
  const words = await cachedRows(s, 'rng-words', ['LootboxRngApplied'], {}, row, signal);
  const applied = latestBefore(words, row);
  if (!applied) return null;
  const word = BigInt(applied.args.word);
  return afkingSpinMatches({ betId: a.betId, playerId, word, day: delivery.day }) ? delivery : null;
}
